from AlgorithmImports import *
from decimal import Decimal
from math import floor


class StrategySystemAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily, fillForward=False
            ).Symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_samples = 0
        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        bars = {}
        complete_slice = True
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                complete_slice = False
            else:
                bars[ticker] = data.Bars[symbol]

        spy_bar = bars.get("SPY")
        if spy_bar is not None:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_samples += 1

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if complete_slice:
            indicators_ready = (
                self.spy_samples > 100
                and self.spy_sma.IsReady
                and self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.aapl_rsi.IsReady
                and self.previous_aapl_close is not None
            )

            if indicators_ready:
                spy_close = spy_bar.Close
                spy_sma = self.spy_sma.Current.Value

                spy_crossed_below = (
                    self.previous_spy_close >= self.previous_spy_sma
                    and spy_close < spy_sma
                )
                if self.strategy_a_shares > 0 and spy_crossed_below:
                    self.MarketOrder(
                        self.symbols["SPY"], -self.strategy_a_shares,
                        tag="Strategy A sell"
                    )
                    self.strategy_a_shares = 0

                if (
                    self.strategy_b_shares > 0
                    and self.aapl_rsi.Current.Value > 60
                ):
                    self.MarketOrder(
                        self.symbols["AAPL"], -self.strategy_b_shares,
                        tag="Strategy B sell"
                    )
                    self.strategy_b_shares = 0

                spy_crossed_above = (
                    self.previous_spy_close <= self.previous_spy_sma
                    and spy_close > spy_sma
                )
                if self.strategy_a_shares == 0 and spy_crossed_above:
                    quantity = floor(
                        self.Portfolio.TotalPortfolioValue * 0.40 / spy_close
                    )
                    if quantity > 0:
                        self.MarketOrder(
                            self.symbols["SPY"], quantity,
                            tag="Strategy A buy"
                        )
                        self.strategy_a_shares = quantity

                if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
                    allocation = Decimal("20000")
                    if self.Portfolio.Cash >= allocation:
                        quantity = floor(allocation / aapl_bar.Close)
                        if quantity > 0:
                            self.MarketOrder(
                                self.symbols["AAPL"], quantity,
                                tag="Strategy B buy"
                            )
                            self.strategy_b_shares = quantity

        if spy_bar is not None and self.spy_sma.IsReady:
            self.previous_spy_close = spy_bar.Close
            self.previous_spy_sma = self.spy_sma.Current.Value
        if aapl_bar is not None:
            self.previous_aapl_close = aapl_bar.Close

from AlgorithmImports import *
from collections import deque
import math


class TwoSlotStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=101)
        self.aapl_closes = deque(maxlen=15)

        self.spy_lot = 0
        self.aapl_lot = 0

        self.rsi_gain = None
        self.rsi_loss = None
        self.rsi_seed_gains = []
        self.rsi_seed_losses = []
        self.aapl_rsi = None

    def OnData(self, data):
        bars = {}
        complete_slice = True
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                complete_slice = False
                continue
            bars[ticker] = data.Bars[symbol]

        if "SPY" in bars:
            self.spy_closes.append(float(bars["SPY"].Close))
        if "AAPL" in bars:
            self._update_aapl(float(bars["AAPL"].Close))

        if not complete_slice:
            return

        spy_ready = len(self.spy_closes) == 101
        aapl_red_ready = len(self.aapl_closes) >= 4
        aapl_rsi_ready = self.aapl_rsi is not None

        spy_crossed_above = False
        spy_crossed_below = False
        if spy_ready:
            closes = list(self.spy_closes)
            previous_sma = sum(closes[:100]) / 100.0
            current_sma = sum(closes[1:]) / 100.0
            spy_crossed_above = (
                closes[-2] <= previous_sma and closes[-1] > current_sma
            )
            spy_crossed_below = (
                closes[-2] >= previous_sma and closes[-1] < current_sma
            )

        # All sells are evaluated before any buys.
        if self.spy_lot > 0 and spy_ready and spy_crossed_below:
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot, tag="Strategy A sell")
            self.spy_lot = 0

        if self.aapl_lot > 0 and aapl_rsi_ready and self.aapl_rsi > 60.0:
            self.MarketOrder(
                self.symbols["AAPL"], -self.aapl_lot, tag="Strategy B sell"
            )
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_ready and spy_crossed_above:
            close = float(bars["SPY"].Close)
            quantity = int(math.floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / close))
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity, tag="Strategy A buy")
                self.spy_lot = quantity

        if self.aapl_lot == 0 and aapl_red_ready:
            closes = list(self.aapl_closes)
            red_for_three_days = all(
                closes[index] < closes[index - 1]
                for index in range(len(closes) - 3, len(closes))
            )
            if red_for_three_days and float(self.Portfolio.Cash) >= 20_000.0:
                close = float(bars["AAPL"].Close)
                quantity = int(math.floor(20_000.0 / close))
                if quantity > 0:
                    self.MarketOrder(
                        self.symbols["AAPL"], quantity, tag="Strategy B buy"
                    )
                    self.aapl_lot = quantity

    def _update_aapl(self, close):
        if self.aapl_closes:
            change = close - self.aapl_closes[-1]
            gain = max(change, 0.0)
            loss = max(-change, 0.0)

            if self.rsi_gain is None:
                self.rsi_seed_gains.append(gain)
                self.rsi_seed_losses.append(loss)
                if len(self.rsi_seed_gains) == 14:
                    self.rsi_gain = sum(self.rsi_seed_gains) / 14.0
                    self.rsi_loss = sum(self.rsi_seed_losses) / 14.0
            else:
                self.rsi_gain = (self.rsi_gain * 13.0 + gain) / 14.0
                self.rsi_loss = (self.rsi_loss * 13.0 + loss) / 14.0

            if self.rsi_gain is not None:
                if self.rsi_loss == 0.0:
                    self.aapl_rsi = 100.0 if self.rsi_gain > 0.0 else 50.0
                else:
                    relative_strength = self.rsi_gain / self.rsi_loss
                    self.aapl_rsi = 100.0 - 100.0 / (1.0 + relative_strength)

        self.aapl_closes.append(close)

