class StrategySystemAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi_changes = 0
        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.aapl_initial_gain = 0.0
        self.aapl_initial_loss = 0.0
        self.aapl_rsi = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        bars = data.Bars
        all_bars_present = all(bars.ContainsKey(symbol) for symbol in self.symbols.values())

        spy_bar = bars[self.symbols["SPY"]] if bars.ContainsKey(self.symbols["SPY"]) else None
        aapl_bar = bars[self.symbols["AAPL"]] if bars.ContainsKey(self.symbols["AAPL"]) else None

        spy_crosses_above = False
        spy_crosses_below = False
        spy_ready = False
        if spy_bar is not None:
            spy_close = float(spy_bar.Close)
            if len(self.spy_closes) == 100:
                today_sma = (sum(self.spy_closes) - self.spy_closes[0] + spy_close) / 100.0
                spy_ready = self.spy_previous_close is not None and self.spy_previous_sma is not None
                if spy_ready:
                    spy_crosses_above = (
                        self.spy_previous_close <= self.spy_previous_sma
                        and spy_close > today_sma
                    )
                    spy_crosses_below = (
                        self.spy_previous_close >= self.spy_previous_sma
                        and spy_close < today_sma
                    )
                self.spy_previous_sma = today_sma
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == 100 and self.spy_previous_sma is None:
                self.spy_previous_sma = sum(self.spy_closes) / 100.0
            self.spy_previous_close = spy_close

        aapl_ready = False
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is not None:
                change = aapl_close - self.aapl_previous_close
                if change < 0:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

                gain = max(change, 0.0)
                loss = max(-change, 0.0)
                if self.aapl_rsi_changes < 14:
                    self.aapl_initial_gain += gain
                    self.aapl_initial_loss += loss
                    self.aapl_rsi_changes += 1
                    if self.aapl_rsi_changes == 14:
                        self.aapl_average_gain = self.aapl_initial_gain / 14.0
                        self.aapl_average_loss = self.aapl_initial_loss / 14.0
                else:
                    self.aapl_average_gain = (self.aapl_average_gain * 13.0 + gain) / 14.0
                    self.aapl_average_loss = (self.aapl_average_loss * 13.0 + loss) / 14.0

                if self.aapl_rsi_changes >= 14:
                    if self.aapl_average_loss == 0:
                        self.aapl_rsi = 100.0 if self.aapl_average_gain > 0 else 50.0
                    else:
                        relative_strength = self.aapl_average_gain / self.aapl_average_loss
                        self.aapl_rsi = 100.0 - 100.0 / (1.0 + relative_strength)
                    aapl_ready = True
            self.aapl_previous_close = aapl_close

        if not all_bars_present:
            return

        if spy_ready:
            if self.strategy_a_shares > 0 and spy_crosses_below:
                self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0

            if self.strategy_a_shares == 0 and spy_crosses_above:
                shares = math.floor(
                    0.40 * float(self.Portfolio.TotalPortfolioValue) / float(spy_bar.Close)
                )
                if shares > 0:
                    self.MarketOrder(self.symbols["SPY"], shares)
                    self.strategy_a_shares = shares

        if aapl_ready:
            if self.strategy_b_shares > 0 and self.aapl_rsi > 60.0:
                self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0

            if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
                allocation = 20_000.0
                if float(self.Portfolio.Cash) >= allocation:
                    shares = math.floor(allocation / float(aapl_bar.Close))
                    if shares > 0:
                        self.MarketOrder(self.symbols["AAPL"], shares)
                        self.strategy_b_shares = shares

from AlgorithmImports import *


class TwoSlotStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        bars = data.Bars
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma

        if bars.ContainsKey(spy):
            spy_bar = bars[spy]
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            current_spy_sma = self.spy_sma.Current.Value if self.spy_sma.IsReady else None
        else:
            spy_bar = None
            current_spy_sma = None

        if bars.ContainsKey(aapl):
            aapl_bar = bars[aapl]
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_bar.Close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
        else:
            aapl_bar = None

        all_bars_present = all(
            bars.ContainsKey(self.symbols[ticker]) for ticker in self.tickers
        )

        indicators_ready = (
            current_spy_sma is not None
            and previous_spy_close is not None
            and previous_spy_sma is not None
            and self.aapl_rsi.IsReady
            and self.previous_aapl_close is not None
        )

        if all_bars_present and indicators_ready:
            spy_crossed_above = (
                previous_spy_close <= previous_spy_sma
                and spy_bar.Close > current_spy_sma
            )
            spy_crossed_below = (
                previous_spy_close >= previous_spy_sma
                and spy_bar.Close < current_spy_sma
            )

            # Sells are evaluated before buys.
            if self.strategy_a_shares > 0 and spy_crossed_below:
                self.MarketOrder(spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

            if (
                self.strategy_b_shares > 0
                and self.aapl_rsi.Current.Value > 60
            ):
                self.MarketOrder(aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

            if self.strategy_a_shares == 0 and spy_crossed_above:
                quantity = self.CalculateOrderQuantity(spy, 0.40)
                if quantity > 0:
                    self.MarketOrder(spy, quantity)
                    self.strategy_a_shares = quantity

            if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20_000:
                    quantity = int(20_000 // aapl_bar.Close)
                    if quantity > 0:
                        self.MarketOrder(aapl, quantity)
                        self.strategy_b_shares = quantity

        if spy_bar is not None:
            self.previous_spy_close = spy_bar.Close
            self.previous_spy_sma = current_spy_sma

        if aapl_bar is not None:
            self.previous_aapl_close = aapl_bar.Close

from AlgorithmImports import *
from collections import deque
from math import floor


class TwoSlotDailyStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.closes = {symbol: deque(maxlen=100) for symbol in self.symbols}
        self.previous_close = {symbol: None for symbol in self.symbols}

        self.spy_previous_sma = None
        self.aapl_red_streak = 0

        self.rsi_period = 14
        self.rsi_changes = deque(maxlen=self.rsi_period)
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        bars = {}
        for symbol in self.symbols:
            if data.Bars.ContainsKey(symbol):
                bars[symbol] = data.Bars[symbol]

        spy_sma = None
        aapl_rsi = self.aapl_rsi

        for symbol, bar in bars.items():
            close = float(bar.Close)
            old_close = self.previous_close[symbol]

            if symbol == self.aapl and old_close is not None:
                if close < old_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
                aapl_rsi = self._update_aapl_rsi(close - old_close)

            self.closes[symbol].append(close)
            self.previous_close[symbol] = close

            if symbol == self.spy and len(self.closes[symbol]) == 100:
                spy_sma = sum(self.closes[symbol]) / 100.0

        if len(bars) != len(self.symbols):
            if spy_sma is not None:
                self.spy_previous_sma = spy_sma
            return

        spy_close = float(bars[self.spy].Close)
        aapl_close = float(bars[self.aapl].Close)

        spy_crosses_above = False
        spy_crosses_below = False
        spy_history = self.closes[self.spy]
        if spy_sma is not None and self.spy_previous_sma is not None and len(spy_history) >= 2:
            prior_spy_close = list(spy_history)[-2]
            spy_crosses_above = (
                prior_spy_close <= self.spy_previous_sma and spy_close > spy_sma
            )
            spy_crosses_below = (
                prior_spy_close >= self.spy_previous_sma and spy_close < spy_sma
            )

        # All exits are evaluated before either strategy's entry.
        if self.spy_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and aapl_rsi is not None and aapl_rsi > 60.0:
            self.MarketOrder(self.aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crosses_above:
            quantity = floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20_000.0:
                quantity = floor(20_000.0 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.aapl_lot = quantity

        self.spy_previous_sma = spy_sma

    def _update_aapl_rsi(self, change):
        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if self.rsi_average_gain is None:
            self.rsi_changes.append((gain, loss))
            if len(self.rsi_changes) < self.rsi_period:
                return None
            self.rsi_average_gain = sum(item[0] for item in self.rsi_changes) / self.rsi_period
            self.rsi_average_loss = sum(item[1] for item in self.rsi_changes) / self.rsi_period
        else:
            self.rsi_average_gain = (
                self.rsi_average_gain * (self.rsi_period - 1) + gain
            ) / self.rsi_period
            self.rsi_average_loss = (
                self.rsi_average_loss * (self.rsi_period - 1) + loss
            ) / self.rsi_period

        if self.rsi_average_loss == 0.0:
            self.aapl_rsi = 100.0 if self.rsi_average_gain > 0.0 else 0.0
        else:
            relative_strength = self.rsi_average_gain / self.rsi_average_loss
            self.aapl_rsi = 100.0 - 100.0 / (1.0 + relative_strength)
        return self.aapl_rsi
